function indicePagina() {
  // SUMÁRIO — campo TOC do Word (atualizado automaticamente com Ctrl+A → F9)
  return `
    ${pc('SUMÁRIO', '28', true, '360', '240')}
    ${linhaHoriz('000000','4')}
    <w:p><w:pPr><w:spacing w:before="120" w:after="60"/></w:pPr>
      <w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="20"/><w:color w:val="555555"/><w:i/></w:rPr>
        <w:t>[ Para atualizar o sumário: selecione tudo (Ctrl+A) e pressione F9 ]</w:t></w:r>
    </w:p>
    <w:p><w:pPr><w:spacing w:before="0" w:after="0"/></w:pPr>
      <w:r><w:fldChar w:fldCharType="begin" w:dirty="true"/></w:r>
      <w:r><w:instrText xml:space="preserve"> TOC \\o "1-2" \\h \\z \\u </w:instrText></w:r>
      <w:r><w:fldChar w:fldCharType="separate"/></w:r>
      <w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="24"/><w:color w:val="000000"/></w:rPr>
        <w:t>Gerando sumário…</w:t></w:r>
      <w:r><w:fldChar w:fldCharType="end"/></w:r>
    </w:p>
  `;
}

function dadosEmpresaTabela() {
  const rows = [['Campo', 'Informação']];
  if (e('razaoSocial')) rows.push(['Razão Social', e('razaoSocial')]);
  if (e('nomeFantasia')) rows.push(['Nome Fantasia', e('nomeFantasia')]);
  if (e('cnpj')) rows.push(['CNPJ', e('cnpj')]);
  if (e('endereco')) rows.push(['Endereço', e('endereco')]);
  if (e('municipio')) rows.push(['Município/UF', e('municipio') + ' – ' + e('uf')]);
  if (e('cep')) rows.push(['CEP', e('cep')]);
  if (e('telefone')) rows.push(['Telefone', e('telefone')]);
  if (e('coordE')) rows.push(['Coordenadas UTM', e('coordE') + ' m E / ' + e('coordN') + ' m N – Zona ' + e('zonaUtm')]);
  return tabelaSimples(rows);
}

